check "PriorityClass pipeline-critical: value 1000000, PreemptLowerPriority, not global default" bash -c "[ \"\$(kubectl --context main get priorityclass pipeline-critical -o jsonpath='{.value} {.preemptionPolicy} {.globalDefault}')\" = '1000000 PreemptLowerPriority false' ] || [ \"\$(kubectl --context main get priorityclass pipeline-critical -o jsonpath='{.value} {.preemptionPolicy} {.globalDefault}')\" = '1000000 PreemptLowerPriority ' ]"
check "ingest uses pipeline-critical and a hard hostname spread with max skew 1" bash -c "[ \"\$(kubectl --context main -n pipeline get deploy ingest -o jsonpath='{.spec.template.spec.priorityClassName} {.spec.template.spec.topologySpreadConstraints[0].maxSkew} {.spec.template.spec.topologySpreadConstraints[0].topologyKey} {.spec.template.spec.topologySpreadConstraints[0].whenUnsatisfiable}')\" = 'pipeline-critical 1 kubernetes.io/hostname DoNotSchedule' ]"
check "deployment ingest has 3 ready replicas" deploy_ready main ingest pipeline 3
check "ingest pods run on both workers (2+1), none on the control plane" bash -c "nodes=\$(kubectl --context main -n pipeline get pods -l app=ingest --field-selector=status.phase=Running -o jsonpath='{range .items[*]}{.spec.nodeName}{\"\\n\"}{end}' | sort | uniq -c | awk '{print \$1\":\"\$2}' | sort | tr '\n' ' '); [ \"\$nodes\" = \"1:$MAIN_W1 2:$MAIN_W2 \" ] || [ \"\$nodes\" = \"1:$MAIN_W2 2:$MAIN_W1 \" ]"
